const { ApolloServer, gql } = require('@apollo/server');
const { expressMiddleware } = require('@apollo/server/express4');
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

// User database simulation
const users = [
  { id: '1', email: 'admin@corp.io', balance: 50000, role: 'admin' },
  { id: '2', email: 'user@corp.io', balance: 1000, role: 'user' }
];

const typeDefs = gql`
  type User {
    id: ID!
    email: String!
    balance: Float!
    role: String!
  }

  type TransferResult {
    success: Boolean!
    message: String!
    newBalance: Float
  }

  type Query {
    me: User
    users: [User]
  }

  type Mutation {
    transferFunds(toUserId: ID!, amount: Float!): TransferResult!
    updateEmail(newEmail: String!): User!
    promoteUser(userId: ID!): User!
  }
`;

const resolvers = {
  Query: {
    me: (_, __, { user }) => {
      if (!user) throw new Error('Not authenticated');
      return users.find(u => u.id === user.id);
    },
    users: (_, __, { user }) => {
      if (!user || user.role !== 'admin') throw new Error('Forbidden');
      return users;
    }
  },
  Mutation: {
    transferFunds: (_, { toUserId, amount }, { user }) => {
      if (!user) throw new Error('Not authenticated');
      const sender = users.find(u => u.id === user.id);
      const receiver = users.find(u => u.id === toUserId);
      if (!receiver) return { success: false, message: 'Recipient not found' };
      if (sender.balance < amount) return { success: false, message: 'Insufficient funds' };
      sender.balance -= amount;
      receiver.balance += amount;
      return { success: true, message: `Transferred ${amount}`, newBalance: sender.balance };
    },
    updateEmail: (_, { newEmail }, { user }) => {
      if (!user) throw new Error('Not authenticated');
      const u = users.find(u => u.id === user.id);
      u.email = newEmail;
      return u;
    },
    promoteUser: (_, { userId }, { user }) => {
      if (!user || user.role !== 'admin') throw new Error('Forbidden');
      const target = users.find(u => u.id === userId);
      target.role = 'admin';
      return target;
    }
  }
};

async function startServer() {
  const app = express();

  // CORS configured to allow credentials from any origin
  app.use(cors({
    origin: true,
    credentials: true
  }));

  app.use(express.json());

  // Session-based auth via cookie - no CSRF token validation
  app.use((req, res, next) => {
    const sessionId = req.cookies?.session_id || req.headers['x-session-id'];
    if (sessionId) {
      // Lookup session -> user mapping (simplified)
      const sessionStore = global.sessionStore || {};
      req.user = sessionStore[sessionId] || null;
    }
    next();
  });

  const server = new ApolloServer({
    typeDefs,
    resolvers,
    csrfPrevention: false, // Explicitly disabled for "compatibility"
    introspection: true
  });

  await server.start();

  app.use('/graphql', expressMiddleware(server, {
    context: async ({ req }) => ({
      user: req.user
    })
  }));

  app.listen(4000, () => {
    console.log('GraphQL server running on http://localhost:4000/graphql');
  });
}

startServer();
